import{_ as l,a0 as o,w as p,s as r,ao as d,I as i,x as a,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"全面介紹 Linux 權限 | LCTT x X-CMD","titleTemplate":false,"description":"全面介紹 Linux 權限 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"全面介紹 Linux 權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"全面介紹 Linux 權限 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20190801 Linux permissions 101","title":"全面介紹 Linux 權限","tag":"201911","desc":""},"relativePath":"201911/20190801 Linux permissions 101.md","filePath":"[post].md"}'),c={name:"201911/20190801 Linux permissions 101.md"};function h(g,s,k,u,b,f){const e=o("Link");return p(),r("div",null,[s[28]||(s[28]=d(`<h1 id="全面介紹-linux-權限" tabindex="-1">全面介紹 Linux 權限 <a class="header-anchor" href="#全面介紹-linux-權限" aria-label="Permalink to “全面介紹 Linux 權限”">​</a></h1><blockquote><p>知道如何控制用户對文件的訪問是一項基本的系統管理技能。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201911/08/233101y043rn4ua00r3lqn.jpg" alt=""></p><p>瞭解 Linux 權限以及如何控制哪些用户可以訪問文件是系統管理的一項基本技能。</p><p>本文將介紹標準 Linux 文件系統權限，並進一步研究特殊權限，以及使用 <code>umask</code> 來解釋默認權限作為文章的結束。</p><h3 id="理解-ls-命令的輸出" tabindex="-1">理解 ls 命令的輸出 <a class="header-anchor" href="#理解-ls-命令的輸出" aria-label="Permalink to “理解 ls 命令的輸出”">​</a></h3><p>在討論如何修改權限之前，我們需要知道如何查看權限。通過 <code>ls</code> 命令的長列表參數（<code>-l</code>）為我們提供了有關文件的許多信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lAh</span></span>
<span class="line"><span>total 20K</span></span>
<span class="line"><span>-rwxr-xr--+ 1 root root    0 Mar  4 19:39 file1</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root    0 Mar  4 19:39 file10</span></span>
<span class="line"><span>-rwxrwxr--+ 1 root root    0 Mar  4 19:39 file2</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root    0 Mar  4 19:39 file8</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root    0 Mar  4 19:39 file9</span></span>
<span class="line"><span>drwxrwxrwx. 2 root root 4.0K Mar  4 20:04 testdir</span></span></code></pre></div><p>為了理解這些是什麼意思，讓我們將關於權限的輸出分解為各個部分。單獨理解每個部分會更容易。</p><p>讓我們看看在上面的輸出中的最後一行的每個組件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrwxrwx. 2 root root 4.0K Mar  4 20:04 testdir</span></span></code></pre></div><div class="table-wrap"><table><thead><tr><th>第 1 節</th><th>第 2 節</th><th>第 3 節</th><th>第 4 節</th><th>第 5 節</th><th>第 6 節</th><th>第 7 節</th></tr></thead><tbody><tr><td><code>d</code></td><td><code>rwx</code></td><td><code>rwx</code></td><td><code>rwx</code></td><td><code>.</code></td><td><code>root</code></td><td><code>root</code></td></tr></tbody></table></div><p>第 1 節（左側）顯示文件的類型。</p><div class="table-wrap"><table><thead><tr><th>符號</th><th>類型</th></tr></thead><tbody><tr><td><code>d</code></td><td>目錄</td></tr><tr><td><code>-</code></td><td>常規文件</td></tr><tr><td><code>l</code></td><td>軟鏈接</td></tr></tbody></table></div>`,14)),i("p",null,[s[1]||(s[1]=i("code",null,"ls",-1)),s[2]||(s[2]=a(" 的 ",-1)),n(e,{href:"https://www.gnu.org/software/texinfo/manual/info-stnd/info-stnd.html"},{default:t(()=>[...s[0]||(s[0]=[a("info 頁面",-1)])]),_:1}),s[3]||(s[3]=a("完整列出了不同的文件類型。",-1))]),s[29]||(s[29]=d(`<p>每個文件都有三種訪問方式：</p><ul><li>屬主</li><li>組</li><li>所有其他人    第 2、3 和 4 節涉及用户（屬主）、組和“其他用户”權限。每個部分都可以包含 <code>r</code>（讀取）、<code>w</code>（寫入）和 <code>x</code>（執行）權限的組合。</li></ul><p>每個權限還分配了一個數值，這在以八進制表示形式討論權限時很重要。</p><div class="table-wrap"><table><thead><tr><th>權限</th><th>八進制值</th></tr></thead><tbody><tr><td><code>r</code></td><td>4</td></tr><tr><td><code>w</code></td><td>2</td></tr><tr><td><code>x</code></td><td>1</td></tr></tbody></table></div><p>第 5 節描述了其他替代訪問方法，例如 SELinux 或文件訪問控制列表（FACL）。</p><div class="table-wrap"><table><thead><tr><th>訪問方法</th><th>字符</th></tr></thead><tbody><tr><td>沒有其它訪問方法</td><td><code>-</code></td></tr><tr><td>SELinux</td><td><code>.</code></td></tr><tr><td>FACL</td><td><code>+</code></td></tr><tr><td>各種方法的組合</td><td><code>+</code></td></tr></tbody></table></div><p>第 6 節和第 7 節分別是屬主和組的名稱。</p><h3 id="使用-chown-和-chmod" tabindex="-1">使用 chown 和 chmod <a class="header-anchor" href="#使用-chown-和-chmod" aria-label="Permalink to “使用 chown 和 chmod”">​</a></h3><h4 id="chown-命令" tabindex="-1">chown 命令 <a class="header-anchor" href="#chown-命令" aria-label="Permalink to “chown 命令”">​</a></h4><p><code>chown</code>（更改所有權）命令用於更改文件的用户和組的所有權。</p><p>要將文件 <code>foo</code> 的用户和組的所有權更改為 <code>root</code>，我們可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown root:root foo</span></span>
<span class="line"><span>$ chown root: foo</span></span></code></pre></div><p>在用户名後跟冒號（<code>:</code>）運行該命令將同時設置用户和組所有權。</p><p>要僅將文件 <code>foo</code> 的用户所有權設置為 <code>root</code> 用户，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown root foo</span></span></code></pre></div><p>要僅更改文件 <code>foo</code> 的組所有權，請在組之前加冒號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown :root foo</span></span></code></pre></div><h4 id="chmod-命令" tabindex="-1">chmod 命令 <a class="header-anchor" href="#chmod-命令" aria-label="Permalink to “chmod 命令”">​</a></h4><p><code>chmod</code>（更改模式）命令控制屬主、組以及既不是屬主也不屬於與文件關聯的組的所有其他用户的文件許可權。</p><p><code>chmod</code> 命令可以以八進制（例如 <code>755</code>、<code>644</code> 等）和符號（例如 <code>u+rwx</code>、<code>g-rwx</code>、<code>o=rw</code>）格式設置權限。</p><p>八進制表示法將 4 個“點”分配給“讀取”，將 2 個“點”分配給“寫入”，將 1 個點分配給“執行”。如果要給用户（屬主）分配“讀取”權限，則將 4 分配給第一個插槽，但是如果要添加“寫入”權限，則必須添加 2。如果要添加“執行”，則要添加 1。我們對每種權限類型執行此操作：屬主、組和其他。</p><p>例如，如果我們想將“讀取”、“寫入”和“執行”分配給文件的屬主，但僅將“讀取”和“執行”分配給組成員和所有其他用户，則我們應使用 <code>755</code>（八進制格式）。這是屬主的所有權限位（<code>4+2+1</code>），但組和其他權限的所有權限位只有 <code>4</code> 和 <code>1</code>（<code>4+1</code>）。</p><blockquote><p>細分為：4+2+1=7，4+1=5 和 4+1=5。</p></blockquote><p>如果我們想將“讀取”和“寫入”分配給文件的屬主，而只將“讀取”分配給組的成員和所有其他用户，則可以如下使用 <code>chmod</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 644 foo_file</span></span></code></pre></div><p>在下面的示例中，我們在不同的分組中使用符號表示法。注意字母 <code>u</code>、<code>g</code> 和 <code>o</code> 分別代表“用户”（屬主）、“組”和“其他”。我們將 <code>u</code>、<code>g</code> 和 <code>o</code> 與 <code>+</code>、<code>-</code> 或 <code>=</code> 結合使用來添加、刪除或設置權限位。</p><p>要將“執行”位添加到所有權權限集中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod u+x foo_file</span></span></code></pre></div><p>要從組成員中刪除“讀取”、“寫入”和“執行”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod g-rwx foo_file</span></span></code></pre></div><p>要將所有其他用户的所有權設置為“讀取”和“寫入”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod o=rw</span></span></code></pre></div><h3 id="特殊位-設置-uid、設置-gid-和粘滯位" tabindex="-1">特殊位：設置 UID、設置 GID 和粘滯位 <a class="header-anchor" href="#特殊位-設置-uid、設置-gid-和粘滯位" aria-label="Permalink to “特殊位：設置 UID、設置 GID 和粘滯位”">​</a></h3><p>除了標準權限外，還有一些特殊的權限位，它們具有一些別的用處。</p><h4 id="設置用户-id-suid" tabindex="-1">設置用户 ID（suid） <a class="header-anchor" href="#設置用户-id-suid" aria-label="Permalink to “設置用户 ID（suid）”">​</a></h4>`,35)),i("p",null,[s[5]||(s[5]=a("當在文件上設置 ",-1)),s[6]||(s[6]=i("code",null,"suid",-1)),s[7]||(s[7]=a(" 時，將以文件的屬主的身份而不是運行該文件的用户身份執行操作。一個",-1)),n(e,{href:"https://www.theurbanpenguin.com/using-a-simple-c-program-to-explain-the-suid-permission/"},{default:t(()=>[...s[4]||(s[4]=[a("好的例子",-1)])]),_:1}),s[8]||(s[8]=a("是 ",-1)),s[9]||(s[9]=i("code",null,"passwd",-1)),s[10]||(s[10]=a(" 命令。它需要設置 ",-1)),s[11]||(s[11]=i("code",null,"suid",-1)),s[12]||(s[12]=a(" 位，以便更改密碼的操作具有 root 權限。",-1))]),s[30]||(s[30]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /bin/passwd</span></span>
<span class="line"><span>-rwsr-xr-x. 1 root root 27832 Jun 10  2014 /bin/passwd</span></span></code></pre></div><p>設置 <code>suid</code> 位的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod u+s /bin/foo_file_name</span></span></code></pre></div><h4 id="設置組-id-sgid" tabindex="-1">設置組 ID（sgid） <a class="header-anchor" href="#設置組-id-sgid" aria-label="Permalink to “設置組 ID（sgid）”">​</a></h4><p><code>sgid</code> 位與 <code>suid</code> 位類似，操作是在目錄的組所有權下完成的，而不是以運行命令的用户身份。</p><p>一個使用 <code>sgid</code> 的例子是，如果多個用户正在同一個目錄中工作，並且目錄中創建的每個文件都需要具有相同的組權限。下面的示例創建一個名為 <code>collab_dir</code> 的目錄，設置 <code>sgid</code> 位，並將組所有權更改為 <code>webdev</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir collab_dir</span></span>
<span class="line"><span>$ chmod g+s collab_dir</span></span>
<span class="line"><span>$ chown :webdev collab_dir</span></span></code></pre></div><p>現在，在該目錄中創建的任何文件都將具有 <code>webdev</code> 的組所有權，而不是創建該文件的用户的組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd collab_dir</span></span>
<span class="line"><span>$ touch file-sgid</span></span>
<span class="line"><span>$ ls -lah file-sgid</span></span>
<span class="line"><span>-rw-r--r--. 1 root webdev 0 Jun 12 06:04 file-sgid</span></span></code></pre></div><h4 id="粘滯-位" tabindex="-1">“粘滯”位 <a class="header-anchor" href="#粘滯-位" aria-label="Permalink to ““粘滯”位”">​</a></h4><p>粘滯位表示，只有文件所有者才能刪除該文件，即使組權限允許該文件可以刪除。通常，在 <code>/tmp</code> 這樣的通用或協作目錄上，此設置最有意義。在下面的示例中，“所有其他人”權限集的“執行”列中的 <code>t</code> 表示已應用粘滯位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -ld /tmp</span></span>
<span class="line"><span>drwxrwxrwt. 8 root root 4096 Jun 12 06:07 /tmp/</span></span></code></pre></div><p>請記住，這不會阻止某個人編輯該文件，它只是阻止他們刪除該目錄的內容（LCTT 譯註：即刪除目錄下文件）。</p><p>我們將粘滯位設置為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod o+t foo_dir</span></span></code></pre></div><p>你可以自己嘗試在目錄上設置粘滯位並賦予其完整的組權限，以便多個屬於同一組的用户可以在目錄上進行讀取、寫入和執行。</p><p>接着，以每個用户的身份創建文件，然後嘗試以另一個用户的身份刪除它們。</p><p>如果一切配置正確，則一個用户應該不能從另一用户那裏刪除文件。</p><p>請注意，這些位中的每個位也可以用八進制格式設置：SUID = 4、SGID = 2 和 粘滯位 = 1。（LCTT 譯註：這裏是四位八進制數字）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 4744</span></span>
<span class="line"><span>$ chmod 2644</span></span>
<span class="line"><span>$ chmod 1755</span></span></code></pre></div><h4 id="大寫還是小寫" tabindex="-1">大寫還是小寫？ <a class="header-anchor" href="#大寫還是小寫" aria-label="Permalink to “大寫還是小寫？”">​</a></h4><p>如果要設置特殊位時看到大寫的 <code>S</code> 或 <code>T</code> 而不是小寫的字符（如我們之前所見），那是因為不存在（對應的）底層的執行位。為了説明這一點，下面的示例創建一個設置了粘滯位的文件。然後，我們可以添加和刪除執行位以演示大小寫更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch file cap-ST-demo</span></span>
<span class="line"><span>$ chmod 1755 cap-ST-demo</span></span>
<span class="line"><span>$ ls -l cap-ST-demo</span></span>
<span class="line"><span>-rwxr-xr-t. 1 root root 0 Jun 12 06:16 cap-ST-demo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ chmod o-x cap-X-demo</span></span>
<span class="line"><span>$ ls -l cap-X-demo</span></span>
<span class="line"><span>-rwxr-xr-T. 1 root root 0 Jun 12 06:16 cap-ST-demo</span></span></code></pre></div><h4 id="有條件地設置執行位" tabindex="-1">有條件地設置執行位 <a class="header-anchor" href="#有條件地設置執行位" aria-label="Permalink to “有條件地設置執行位”">​</a></h4><p>至此，我們使用小寫的 <code>x</code> 設置了執行位，而無需詢問任何問題即可對其進行設置。我們還有另一種選擇：使用大寫的 <code>X</code> 而不是小寫的，它將僅在權限組中某個位置已經有執行位時才設置執行位。這可能是一個很難解釋的概念，但是下面的演示將幫助説明它。請注意，在嘗試將執行位添加到組特權之後，該位沒有被設置上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span>
<span class="line"><span>$ chmod g+X cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span></code></pre></div><p>在這個類似的例子中，我們首先使用小寫的 <code>x</code> 將執行位添加到組權限，然後使用大寫的 <code>X</code> 為所有其他用户添加權限。這次，大寫的 <code>X</code>設置了該權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span>
<span class="line"><span>$ chmod g+x cap-X-file</span></span>
<span class="line"><span>$ ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r-xr--. 1 root root 0 Jun 12 06:31 cap-X-file</span></span>
<span class="line"><span>$ chmod o+X cap-X-file</span></span>
<span class="line"><span>ls -l cap-X-file</span></span>
<span class="line"><span>-rw-r-xr-x. 1 root root 0 Jun 12 06:31 cap-X-file</span></span></code></pre></div><h3 id="理解-umask" tabindex="-1">理解 umask <a class="header-anchor" href="#理解-umask" aria-label="Permalink to “理解 umask”">​</a></h3><p><code>umask</code> 會屏蔽（或“阻止”）默認權限集中的位，以定義文件或目錄的權限。例如，<code>umask</code>輸出中的 <code>2</code> 表示它至少在默認情況下阻止了文件的“寫入”位。</p><p>使用不帶任何參數的 <code>umask</code> 命令可以使我們看到當前的 <code>umask</code> 設置。共有四列：第一列為特殊的<code>suid</code>、<code>sgid</code> 或粘滯位而保留，其餘三列代表屬主、組和其他人的權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask</span></span>
<span class="line"><span>0022</span></span></code></pre></div><p>為了理解這意味着什麼，我們可以用 <code>-S</code> 標誌來執行 <code>umask</code>（如下所示）以解釋屏蔽位的結果。例如，由於第三列中的值為 <code>2</code>，因此將“寫入”位從組和其他部分中屏蔽掉了；只能為它們分配“讀取”和“執行”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask -S</span></span>
<span class="line"><span>u=rwx,g=rx,o=rx</span></span></code></pre></div><p>要查看文件和目錄的默認權限集是什麼，讓我們將 <code>umask</code> 設置為全零。這意味着我們在創建文件時不會掩蓋任何位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask 000</span></span>
<span class="line"><span>$ umask -S</span></span>
<span class="line"><span>u=rwx,g=rwx,o=rwx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ touch file-umask-000</span></span>
<span class="line"><span>$ ls -l file-umask-000</span></span>
<span class="line"><span>-rw-rw-rw-. 1 root root 0 Jul 17 22:03 file-umask-000</span></span></code></pre></div><p>現在，當我們創建文件時，我們看到所有部分的默認權限分別為“讀取”（<code>4</code>）和“寫入”（<code>2</code>），相當於八進制表示 <code>666</code>。</p><p>我們可以對目錄執行相同的操作，並看到其默認權限為 <code>777</code>。我們需要在目錄上使用“執行”位，以便可以遍歷它們。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir dir-umask-000</span></span>
<span class="line"><span>$ ls -ld dir-umask-000</span></span>
<span class="line"><span>drwxrwxrwx. 2 root root 4096 Jul 17 22:03 dir-umask-000/</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>管理員還有許多其他方法可以控制對系統文件的訪問。這些權限是 Linux 的基本權限，我們可以在這些基礎上進行構建。如果你的工作為你引入了 FACL 或 SELinux，你會發現它們也建立在這些文件訪問的首要規則之上。</p><hr>`,42)),i("p",null,[s[14]||(s[14]=a("via: ",-1)),n(e,{href:"https://opensource.com/article/19/8/linux-permissions-101"},{default:t(()=>[...s[13]||(s[13]=[a("https://opensource.com/article/19/8/linux-permissions-101",-1)])]),_:1})]),i("p",null,[s[19]||(s[19]=a("作者：",-1)),n(e,{href:"https://opensource.com/users/mralexjuarezhttps://opensource.com/users/marcobravohttps://opensource.com/users/greg-p"},{default:t(()=>[...s[15]||(s[15]=[a("Alex Juarez",-1)])]),_:1}),s[20]||(s[20]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[16]||(s[16]=[a("lujun9972",-1)])]),_:1}),s[21]||(s[21]=a(" 譯者：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1}),s[22]||(s[22]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[23]||(s[23]=[a("LCTT",-1)])]),_:1}),s[26]||(s[26]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[24]||(s[24]=[a("Linux中國",-1)])]),_:1}),s[27]||(s[27]=a(" 榮譽推出",-1))])])}const y=l(c,[["render",h]]);export{w as __pageData,y as default};
